/* ==== hooks.js ==== */
/* Zentrale Erweiterungspunkte (Noten-Manager und Unterrichts-Manager).
   Statt dass jedes Zusatzmodul eine Grundfunktion (setPage, renderTasksPage, …) selbst umhüllt, meldet es hier
   seine Ergänzung an. Vorteile: eine feste, nachvollziehbare Reihenfolge, ein Fehler in einem Modul bricht die
   übrigen nicht ab, und classroomHooks.list() zeigt jederzeit, wer sich wo eingehängt hat.

   Reihenfolge (entspricht genau den früheren Hüllen; später geladene Module lagen „außen“):
   - before(args):     läuft vor der Grundfunktion – zuletzt angemeldete zuerst.
   - intercept(args):  darf übernehmen; gibt er {handled:true,value} zurück, entfallen die Grundfunktion sowie
                       before/after aller früher angemeldeten Ergänzungen – später angemeldete after laufen weiter.
   - after(result,args): läuft nach der Grundfunktion – zuerst angemeldete zuerst; Rückgabe ≠ undefined ersetzt das Ergebnis.
   - always(args):     läuft zum Schluss immer, auch wenn unterwegs ein Fehler auftrat (wie „finally“). */
(()=>{
 if(window.classroomHooks)return;
 const table={};
 const report=(name,label,e)=>{console.error('Erweiterung „'+label+'“ an '+name+':',e);try{window.classroomLogError?.(e)}catch{}};
 function install(name){
  if(table[name])return table[name];
  const original=window[name];if(typeof original!=='function')throw new Error('classroomHooks: '+name+' ist keine Funktion');
  const entry={name,original,hooks:[]};table[name]=entry;
  window[name]=function(...args){
   const hooks=entry.hooks;let start=0,value,handled=false;
   // before/intercept von außen (zuletzt angemeldet) nach innen
   for(let i=hooks.length-1;i>=0;i--){const h=hooks[i];
    if(h.intercept){let r;try{r=h.intercept.apply(this,args)}catch(e){report(name,h.label,e)}if(r&&r.handled){handled=true;value=r.value;start=i+1;break}}
    if(h.before){try{h.before.apply(this,args)}catch(e){report(name,h.label,e)}}}
   try{
    if(!handled)value=entry.original.apply(this,args);
    // after von innen nach außen; bei Übernahme nur die später angemeldeten
    for(let i=start;i<hooks.length;i++){const h=hooks[i];if(!h.after)continue;try{const r=h.after.call(this,value,args);if(r!==undefined)value=r}catch(e){report(name,h.label,e)}}
   }finally{for(let i=start;i<hooks.length;i++){const h=hooks[i];if(h.always){try{h.always.apply(this,args)}catch(e){report(name,h.label,e)}}}}
   return value};
  return entry}
 window.classroomHooks={
  add(name,label,spec){const entry=install(name);entry.hooks.push({label,...spec});return entry},
  list(){return Object.fromEntries(Object.entries(table).map(([k,v])=>[k,v.hooks.map(h=>h.label+' ['+['intercept','before','after','always'].filter(x=>h[x]).join('+')+']')]))}
 };
})();
;

/* ==== noten/storage-compact.js ==== */
/* Speicher schlank halten (wichtig für Safari/iPad, dort ist der Browserspeicher auf etwa 5 MB begrenzt):
   Der Noten-Manager legt für jede Klasse Datenblätter für alle Seiten des Fachs an – auch für Seiten, die in dieser Klasse
   gar nicht vorkommen. Diese leeren, keiner Rubrik zugeordneten Blätter machten bis zu 90 % des Speichers aus.
   Beim Speichern (und beim Wiederherstellen eines Backups) werden sie weggelassen. Blätter mit Eintragungen bleiben immer erhalten. */
(()=>{
 const statesKey='notenrechner-fachwahl-states-v1',classesKey='notenrechner-klassen-v1';
 const native=Storage.prototype.setItem;
 let lastClasses=null;
 const filled=v=>v!==''&&v!==null&&v!==undefined;
 function hasEntries(page){
  return (page?.students||[]).some(s=>Object.values(s.grades||{}).some(filled)||Object.values(s.rawScores||{}).some(filled)
   ||Object.values(s.statuses||{}).some(v=>filled(v)&&v!=='done')||filled(s.quarterReview?.teacher)||filled(s.quarterReview?.self));
 }
 function currentClasses(){
  try{if(typeof classesBySubject!=='undefined'&&classesBySubject&&Object.keys(classesBySubject).length)return classesBySubject}catch{}
  if(lastClasses)return lastClasses;
  try{return JSON.parse(localStorage.getItem(classesKey)||'null')}catch{return null}
 }
 function compact(states,classes){
  if(!states||typeof states!=='object'||!classes)return {states,removed:0};
  let removed=0;const out={};
  for(const [scope,state] of Object.entries(states)){
   const m=/^(.+)::class::(.+)$/.exec(scope),values=state?.customValues;
   const item=m&&(classes[m[1]]||[]).find(c=>c.id===m[2]);
   if(!item||!values||typeof values!=='object'||!Array.isArray(item.examGroups)){out[scope]=state;continue}
   const keep=new Set(item.examGroups.flatMap(g=>g.pages||[]).filter(Boolean));
   for(const page of Object.values(values))for(const t of page?.tasks||[])if(t?.testDetail?.pageKey)keep.add(t.testDetail.pageKey);
   const nextValues={};
   for(const [key,page] of Object.entries(values)){if(keep.has(key)||hasEntries(page))nextValues[key]=page;else removed++}
   out[scope]={...state,customValues:nextValues};
  }
  return {states:out,removed};
 }
 function compactString(value){
  try{const {states,removed}=compact(JSON.parse(value),currentClasses());return removed?JSON.stringify(states):value}catch{return value}
 }
 // Backup wiederherstellen: mit den Klassen AUS DEM BACKUP verkleinern, bevor geschrieben wird (sonst Speicher voll in Safari).
 let restoring=false;
 window.addEventListener('message',event=>{
  const msg=event.data;if(event.source!==parent||msg?.type!=='classroom:restore'||!msg.values)return;
  try{const raw=msg.values[statesKey],classes=JSON.parse(msg.values[classesKey]||'null');if(typeof raw==='string'&&classes){const {states,removed}=compact(JSON.parse(raw),classes);if(removed)msg.values[statesKey]=JSON.stringify(states)}}catch{}
  restoring=true;setTimeout(()=>restoring=false,0);
 });
 Storage.prototype.setItem=function(key,value){
  if(this===window.localStorage&&!restoring){
   if(key===classesKey){try{lastClasses=JSON.parse(value)}catch{}}
   else if(key===statesKey&&typeof value==='string'&&value.length>20000)value=compactString(value);
  }
  return native.call(this,key,value);
 };
 // Auch im Arbeitsspeicher verkleinern, damit spätere Speichervorgänge schnell bleiben.
 function pruneMemory(){try{if(typeof subjectStates==='undefined'||!subjectStates)return;const classes=currentClasses();const {states}=compact(subjectStates,classes);for(const [scope,state] of Object.entries(states)){const live=subjectStates[scope];if(live?.customValues&&state?.customValues)for(const key of Object.keys(live.customValues))if(!(key in state.customValues))delete live.customValues[key]}}catch{}}
 window.classroomCompactStates=()=>{pruneMemory();const raw=localStorage.getItem(statesKey);if(!raw)return 0;const next=compactString(raw);if(next!==raw)native.call(localStorage,statesKey,next);return raw.length-next.length};
 // Einmalig beim Start den bestehenden Speicher verkleinern.
 window.addEventListener('load',()=>setTimeout(()=>{try{window.classroomCompactStates()}catch{}},500));
})();
;

