      return `<tr><td><div class="task-student-cell"><input type="text" maxlength="60" value="${htmlEscape(student.name)}" placeholder="Name eingeben" aria-label="Name Schüler:in ${index+1}" data-homework-name="${htmlEscape(student.id)}"><button class="student-remove-button" type="button" data-homework-action="remove-student" data-student-id="${htmlEscape(student.id)}" title="Schüler:in entfernen" aria-label="Schüler:in ${index+1} entfernen">−</button></div></td>${statusCells}<td class="homework-missing-count${missing>=3?' is-warning':''}" ${missing>=3&&!group?.material?`role="button" tabindex="0" data-parent-mail-page="${htmlEscape(pageKey)}" data-parent-mail-student="${htmlEscape(student.id)}" aria-label="Eltern-Mail für ${htmlEscape(student.name)} vorbereiten" title="Eltern-Mail vorbereiten${prior?` – davon ${prior} aus früheren Quartalen`:''}"`:prior?`title="davon ${prior} aus früheren Quartalen dieses Halbjahres"`:''}>${missing}</td></tr>`
