      const saved=customPageValues(currentSubject,page.key),total=Math.max(1,Math.floor(Number($(`custom-total-${page.key}`)?.value)||1)),pass=Math.min(1,Math.max(.005,(Number($(`custom-pass-${page.key}`)?.value)||page.defaultPass)/100)),allowHalf=page.base==='text'?!!saved.halfErrors:!!saved.halfPoints;
