const classroomTaskData=taskPageData,classroomHomeworkData=homeworkPageData;
taskPageData=function(subject,key='tasks'){const data=classroomTaskData(subject,key);if(classroomCanonical&&subject===currentSubject)classroomCanonicalRoster(data,classroomSourceKey());classroomFillSharedNames(data,subject);return data};
