   for(const [,page] of entries)for(const student of page?.students||[]){if(!student.name?.trim()||seen.has(student.classroomId||student.id))continue;seen.add(student.classroomId||student.id);students.push({id:student.id,classroomId:student.classroomId,name:student.name,...(student.gender?{gender:student.gender}:{})})}
