    const period=(item.examGroups||[]).find(g=>g.id===group.halfYearId)?.label||'';
    for(const key of group.pages||[]){if(!key)continue;const data=state?.customValues?.[key]||{};const yearGroup=(item.examGroups||[]).find(g=>g.id===group.halfYearId);targets.push({key,quarterIndex:(group.pages||[]).indexOf(key),halfYearId:group.halfYearId,halfYearStart:yearGroup&&typeof classroomPeriodDate==='function'?classroomPeriodDate(yearGroup,'start')||'':'',quarterBoundary:yearGroup&&typeof classroomQuarterBoundary==='function'?classroomQuarterBoundary(yearGroup)||'':'',active:sourceId===classroomSourceKey()&&key===activePage,type:group.material?'material':group.type,label:[period,group.label,(group.type==='homework'&&(!subjectPageSource(subjectId)?.pageNames?.[key]||/^Hausaufgaben/.test(subjectPageSource(subjectId)?.pageNames?.[key]))?`${group.pages.indexOf(key)+1}. Quartal`:subjectPageSource(subjectId)?.pageNames?.[key])].filter(Boolean).filter((label,index,labels)=>index===0||String(label).trim().toLocaleLowerCase('de-DE')!==String(labels[index-1]).trim().toLocaleLowerCase('de-DE')).join(' · '),data});}
