 const data=state.customValues[key];if(!data)return null;const list=data.tasks?'tasks':'assignments',field=list==='tasks'?'grades':'statuses',tasks=(data[list]||[]).filter(t=>t.date===p.date).map(t=>({task:structuredClone(t),index:data[list].indexOf(t)}));
