function classroomStorageDump(){if(subjects[currentSubject])saveCurrentSubject();const result={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith('notenrechner-'))result[key]=localStorage.getItem(key)}return result}
function classroomRestoreStorage(values){window.classroomStorageReplaced=true;const before=classroomStorageDump();try{for(const key of Object.keys(before))localStorage.removeItem(key);for(const [key,value] of Object.entries(values))localStorage.setItem(key,value)}catch(error){for(const key of Object.keys(values))localStorage.removeItem(key);for(const [key,value] of Object.entries(before))localStorage.setItem(key,value);throw error}}
window.addEventListener('message',event=>{
 if(event.source!==parent)return;const msg=event.data;
 try{
  if(msg?.type==='classroom:print'){const button=document.getElementById('exportButton');if(button.disabled)alert('Bitte zuerst ein Fach mit einer druckbaren Seite auswählen.');else button.click();}
  else if(msg?.type==='classroom:request-rosters')parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*');
  else if(msg?.type==='classroom:canonical'){if(classroomApplyCentral(msg.model))parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*');}
  else if(msg?.type==='classroom:select-navigation'){if(msg.subject&&subjects[msg.subject])setSubject(msg.subject);if(msg.classId&&(classesBySubject[currentSubject]||[]).some(c=>c.id===msg.classId))selectClass(msg.classId);parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*');}
  else if(msg?.type==='classroom:manage-classes'){if(msg.source){const parts=msg.source.split('::');setSubject(parts[0]);selectClass(parts.slice(1).join('::'));}if(msg.create)addClass();else openClassRename();parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*');}
  else if(msg?.type==='classroom:record'){const result=classroomRecordValue(msg.payload);parent.postMessage({type:'classroom:record-result',id:msg.id,ok:true,...result},'*');parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*');}
  else if(msg?.type==='classroom:backup-request')parent.postMessage({type:'classroom:backup-result',id:msg.id,values:classroomStorageDump()},'*');
  else if(msg?.type==='classroom:restore'){classroomRestoreStorage(msg.values);parent.postMessage({type:'classroom:restore-result',id:msg.id,ok:true},'*');}
 }catch(error){parent.postMessage({type:msg?.type==='classroom:record'?'classroom:record-result':'classroom:error',id:msg.id,ok:false,message:error.message},'*');}
});
let classroomChangeTimer;
document.addEventListener('change',event=>{
 if(classroomApplying)return;
 const input=event.target,source=classroomSourceKey(),group=classroomCentralGroup(source);
 if(group){let id,date,absent;
  if(input.matches('[data-student-grade]')){id=input.dataset.studentGrade;const panel=input.closest('[data-custom-panel]')||document.querySelector(`[data-student-grade][data-task-id="${CSS.escape(input.dataset.taskId||'')}"]`)?.closest('[data-custom-panel]');if(!panel)return;const data=customPageValues(currentSubject,panel.dataset.customPanel),task=data.tasks?.find(t=>t.id===input.dataset.taskId);date=task?.date;const student=data.students.find(s=>s.id===id);absent=String(student?.grades?.[task?.id]||'').toLowerCase()==='x';if(!absent&&student?.classroomAbsenceGrades)delete student.classroomAbsenceGrades[task?.id];}
  if(input.matches('[data-homework-status]')){id=input.dataset.studentId;/* Die Seite wird beim Speichern neu gezeichnet – das alte Auswahlfeld hängt dann nicht mehr im Dokument. */const panel=input.closest('[data-custom-panel]')||document.querySelector(`[data-homework-status][data-assignment-id="${CSS.escape(input.dataset.assignmentId||'')}"]`)?.closest('[data-custom-panel]');if(!panel)return;const data=customPageValues(currentSubject,panel.dataset.customPanel);date=data.assignments?.find(t=>t.id===input.dataset.assignmentId)?.date;absent=input.value==='absent';if(!absent){const student=data.students.find(s=>s.id===id);if(student?.classroomAbsenceHomework)delete student.classroomAbsenceHomework[input.dataset.assignmentId];}}
  if(id&&date)parent.postMessage({type:'classroom:attendance',classId:group.id,studentId:id,date,absent},'*');
 }
 clearTimeout(classroomChangeTimer);classroomChangeTimer=setTimeout(()=>parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*'),120);
});
