  while(group.pages.length<=index){const used=new Set(source.pages),base=type==='homework'?'homework':'tasks';let key=base,suffix=2;while(used.has(key))key=base+'-'+suffix++;source.pages.push(key);source.pageNames[key]=`${group.pages.length+1}. Quartal`;if(type!=='homework')source.pageSystems[key]='participation';group.pages.push(key);const data=customPageValues(currentSubject,key);data.students=[];if(type==='homework')data.assignments=[];else{data.tasks=[];data.tendencies=false}}
