 const enabled=new Set();
 function displayValue(control){if(control.tagName==='SELECT')return control.selectedOptions[0]?.textContent.trim()||'—';if(control.type==='checkbox')return control.checked?'✓':'—';if(control.type==='date'&&control.value)return control.value.split('-').reverse().join('.');return /^[-+]?\d+\.\d+$/.test(control.value)?control.value.replace('.',','):control.value||'—'}
 function build(panel){const source=panel.querySelector('.table-wrap:not(.compact-table-wrap) table');if(!source)return;const old=panel.querySelector('.compact-table-wrap');const wrap=document.createElement('div');wrap.className='table-wrap compact-table-wrap';const table=source.cloneNode(true);table.className='compact-entry-table';table.removeAttribute('style');
 const remove=[];for(const row of table.rows)for(const cell of row.cells)if(cell.classList.contains('task-add-column')||cell.classList.contains('task-space-column'))remove.push(cell);remove.forEach(c=>c.remove());
 for(const control of table.querySelectorAll('input,select,textarea')){if(control.type==='checkbox'&&control.closest('thead')){control.closest('.task-weight-menu')?.remove();continue}const value=displayValue(control),span=document.createElement('span');span.textContent=control.matches('[data-homework-status]')?({'done':'✓','missing':'✗','excused':'E','absent':'A','':'—'}[control.value]||value):value;span.title=value;span.className=control.className+' compact-cell-value';if(control.matches('[data-homework-status]'))span.dataset.hwStatus=control.value||'none';span.removeAttribute('style');control.replaceWith(span)}
 table.querySelectorAll('button,.task-weight-menu').forEach(n=>n.remove());
 for(const node of table.querySelectorAll('*'))for(const attr of [...node.attributes])if(attr.name==='id'||attr.name==='contenteditable'||attr.name==='tabindex'||(attr.name.startsWith('data-')&&attr.name!=='data-hw-status')||attr.name.startsWith('on'))node.removeAttribute(attr.name);
 let taskIndex=0;
 for(const row of table.rows)for(const cell of row.cells){cell.removeAttribute('style');cell.removeAttribute('width');if(cell.parentElement.parentElement.tagName==='THEAD'){const text=[...cell.querySelectorAll('.compact-cell-value')].map(n=>n.textContent);let label=text.length?text.join(' · '):cell.textContent.replace(/\s+/g,' ').trim();if(source.classList.contains('participation-task-table')){const date=label.match(/\b\d{2}\.\d{2}\.\d{4}\b/);if(date){const extra=[...cell.querySelectorAll('.task-label-input')].map(n=>n.textContent.trim()).find(v=>v&&v!=='—');label=date[0]+(extra?' · '+extra:'')}}else if(source.classList.contains('task-table')&&!source.classList.contains('participation-task-table')&&cell.classList.contains('task-assessment-column'))label='Aufgabe '+(++taskIndex);cell.replaceChildren();const span=document.createElement('span');span.className='compact-heading-label';span.textContent=label;if(cell.cellIndex>0){const face=document.createElement('div');face.className='compact-slanted-heading';face.append(span);cell.append(face)}else cell.append(span);cell.title=label}else{cell.className=cell.className.replace(/task-(?:assessment|student|partial-grade)-cell/g,'')}}
 wrap.append(table);legend(panel);if(old)old.replaceWith(wrap);else panel.append(wrap);
 }
 function sync(){for(const panel of document.querySelectorAll('.panel')){if(panel.hasAttribute('data-quarter-summary')){legend(panel);continue;}if(!panel.querySelector('.table-wrap:not(.compact-table-wrap) table'))continue;const key=panel.dataset.customPanel||panel.id;let toggle=panel.querySelector('[data-compact-toggle]');if(!toggle){const label=document.createElement('label');label.className='toggle compact-view-toggle';toggle=document.createElement('input');toggle.type='checkbox';toggle.setAttribute('role','switch');toggle.dataset.compactToggle='';const caption=document.createElement('span');caption.textContent='Kompaktansicht';label.append(toggle,caption);const heading=panel.querySelector('.section-title'),actions=heading?.querySelector('.task-actions,.semester-table-tools');if(heading){let display=heading.querySelector('.oral-display-actions');if(!display){display=document.createElement('div');display.className='oral-display-actions';heading.append(display)}display.append(label)}else if(actions)actions.append(label);else if(heading)heading.append(label);else panel.prepend(label);toggle.onchange=()=>{if(toggle.checked)enabled.add(key);else enabled.delete(key);panel.classList.toggle('is-compact-view',toggle.checked);if(toggle.checked)build(panel);else panel.querySelector('.compact-table-wrap')?.remove()}}toggle.checked=enabled.has(key);panel.classList.toggle('is-compact-view',toggle.checked);if(toggle.checked)build(panel)}}
