/* ==== noten/parent-mail.js ==== */
// Local, editable parent-mail draft. Nothing is sent or uploaded.
(()=>{
 const dialog=document.createElement('dialog');dialog.className='parent-mail-dialog';dialog.setAttribute('aria-labelledby','parentMailTitle');
 dialog.innerHTML='<h2 id="parentMailTitle">Eltern-Mail vorbereiten</h2><label>Text<textarea data-parent-mail-text rows="12"></textarea></label><p role="status" data-parent-mail-status></p><div class="dialog-actions"><button type="button" class="primary" data-parent-mail-copy>Text kopieren</button><button type="button" data-parent-mail-close>Schließen</button></div>';
 document.body.append(dialog);const text=dialog.querySelector('textarea'),status=dialog.querySelector('[role=status]');let people=[],assignments=[],selectedId=null,mailPage='';
 function ordinal(count){
  const words={0:'nullten',1:'ersten',2:'zweiten',3:'dritten',4:'vierten',5:'fünften',6:'sechsten',7:'siebten',8:'achten',9:'neunten',10:'zehnten',11:'elften',12:'zwölften',13:'dreizehnten',14:'vierzehnten',15:'fünfzehnten',16:'sechzehnten',17:'siebzehnten',18:'achtzehnten',19:'neunzehnten'};
  if(words[count])return words[count];
  const tens={20:'zwanzig',30:'dreißig',40:'vierzig',50:'fünfzig',60:'sechzig',70:'siebzig',80:'achtzig',90:'neunzig'},units=['','ein','zwei','drei','vier','fünf','sechs','sieben','acht','neun'];
  if(count<100){const unit=count%10;return (unit?units[unit]+'und':'')+tens[count-unit]+'sten'}
  return count+'.';
 }
 function draft(){
  const pupil=people.find(p=>p.id===selectedId);if(!pupil)return;
  const parts=pupil.name.split(',').map(p=>p.trim()),first=parts.length>1?parts.slice(1).join(', '):parts[0].split(/\s+/)[0],last=parts.length>1?parts[0]:parts[0].split(/\s+/).slice(1).join(' ');
  const group=typeof classroomCentralGroup==='function'?classroomCentralGroup(classroomSourceKey()):null,person=group?.students.find(p=>p.id===(pupil.classroomId||pupil.id)),gender=person?.gender||pupil.gender,child=gender==='w'?'Ihre Tochter':gender==='m'?'Ihr Sohn':'Ihr Kind',poss=gender==='w'?'ihre':'seine',duties=gender==='w'?'ihren':'seinen';
  const count=assignments.filter(a=>pupil.statuses?.[a.id]==='missing').length+(typeof homeworkPriorMissing==='function'?homeworkPriorMissing(currentSubject,mailPage,pupil):0);
  text.value=`Guten Tag Herr und Frau ${last||'[Nachname]'},\n\n${child} ${first} hat zum ${ordinal(count)} Mal ${poss} Hausaufgaben im Fach ${subjects[currentSubject]?.label||'[Fach]'} nicht oder nur unzureichend angefertigt. Darunter leiden ${poss} mündliche Beteiligung sowie ${poss} methodischen und fachlichen Fähigkeiten. Bitte stellen Sie sicher, dass ${child} ${duties} Pflichten in Zukunft nachkommt.\n\nBitte bestätigen Sie mir kurz, dass Sie diese Nachricht erhalten haben.\n\nMit freundlichen Grüßen\nTorsten Gruber`;
  if(count>=4){const address=gender==='w'?'Ihrer Tochter':gender==='m'?'Ihrem Sohn':'Ihrem Kind',pronoun=gender==='w'?'sie':'es',subjectPronoun=gender==='m'?'er':pronoun;
   text.value=`Guten Tag Herr und Frau ${last||'[Nachname]'},\n\n${child} ${first} hat ${poss} Hausaufgaben im Fach ${subjects[currentSubject]?.label||'[Fach]'} nun zum ${ordinal(count)} Mal nicht oder nur unzureichend angefertigt.\n\nBereits nach dem dritten Mal hatte ich Sie darüber informiert. Leider ${count===4?'ist seitdem eine weitere fehlende Hausaufgabe hinzugekommen':'sind seitdem '+(count-3)+' weitere fehlende Hausaufgaben hinzugekommen'}. Bitte besprechen Sie mit ${address}, wie ${subjectPronoun} ${poss} Hausaufgaben künftig zuverlässig und vollständig erledigen kann.\n\nIch bitte Sie um eine kurze Rückmeldung, dass Sie diese Nachricht zur Kenntnis genommen haben. Bei Schwierigkeiten können wir gern gemeinsam nach einer Lösung suchen.\n\nMit freundlichen Grüßen\nTorsten Gruber`;
  }
  status.textContent='';
 }
 function open(page,id){mailPage=page;const data=homeworkPageData(currentSubject,page);people=data.students.filter(p=>p.name?.trim());assignments=data.assignments;if(!people.length){alert('Bitte zuerst Schüler:innen hinzufügen.');return}selectedId=(people.find(p=>p.id===id)||people[0]).id;draft();dialog.showModal()}
 dialog.querySelector('[data-parent-mail-close]').onclick=()=>dialog.close();dialog.querySelector('[data-parent-mail-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(text.value);dialog.close()}catch{ text.focus();text.select();if(document.execCommand('copy'))dialog.close();else status.textContent='Bitte den markierten Text manuell kopieren.'}};
 function activate(event){const target=event.target.closest('[data-parent-mail-student]');if(!target)return;if(event.type==='keydown'&&!['Enter',' '].includes(event.key))return;event.preventDefault();event.stopPropagation();open(target.dataset.parentMailPage,target.dataset.parentMailStudent)}
 document.addEventListener('click',activate);document.addEventListener('keydown',activate);
})();
;

/* ==== noten/navigation-state.js ==== */
