  if(!manual){inp.disabled=true;inp.title='Im Modus „Automatisch“ gilt die Vorgabe. Zum Ändern „Manuell“ wählen.';wrap?.classList.add('is-disabled');return}
  inp.disabled=false;wrap?.classList.remove('is-disabled');const k=gp?entries.findIndex(e=>e.label==='5'):idx[3];if(k<0)return;inp.value=String(Math.round(entries[k].ratio*1000)/10);inp.title='Verschiebt die Grenze für ausreichend auf der Skala.';
